// Validate demo-proxy's alert and build the Telegram message.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const b = $json.body ?? {};
const errors = [];
const at = new Date(b.at);
if (!b.at || isNaN(at)) errors.push('at missing or not a valid ISO date');
const demo = String(b.demo ?? '').trim();
if (!/^[\w .-]{1,60}$/.test(demo)) errors.push('demo missing or invalid');
if (!['waking', 'opened', 'refused', 'slow'].includes(b.reason)) errors.push('reason must be waking, opened, refused or slow');
const host = b.host == null ? null : String(b.host).slice(0, 120);
const details = b.details && typeof b.details === 'object' ? JSON.stringify(b.details) : null;
if (details && details.length > 4096) errors.push('details over 4 KB');
if (errors.length) throw new Error('Invalid payload: ' + errors.join('; '));

const when = $now.constructor.fromJSDate(at).setZone('Asia/Dubai').toFormat('dd LLL, HH:mm');
const d = b.details ?? {};
const ids = [d.status && `status ${d.status}`, d.rndr_id && `rndr-id ${d.rndr_id}`, d.cf_ray && `cf-ray ${d.cf_ray}`, d.error].filter(Boolean).join(' · ');
const head = `<i>${when} (Dubai)</i>`;
let text;
if (b.reason === 'waking') {
  // A visitor opened a sleeping demo: good news, so no 🚨 (the phone alarm only rings on failures).
  text = `👀 <b>${esc(demo)}: a visitor is opening the demo</b>\n${head}\n\nIt was asleep and is starting now${d.country ? ` (visitor in ${esc(d.country)})` : ''}. A follow-up says when it opens.\n\n${esc(host ?? '')}`;
} else if (b.reason === 'opened') {
  text = `✅ <b>${esc(demo)}: opened for the visitor</b>\n${head}\n\nStarted in ${Number(d.wake_s) || '?'} seconds.\n\n${esc(host ?? '')}`;
} else {
  const what = b.reason === 'refused'
    ? '⛔ Render refused to start it (free-tier wake-up limit). The app isn\'t broken, but visitors can\'t open it until Render allows it again.'
    : '🐢 It did not start within 60 seconds of the visitor\'s request. Check the service logs in the Render dashboard.';
  text = `🚨 <b>${esc(demo)}: a visitor couldn't open the demo</b>\n${head}\n\n${what}\n\n${esc(host ?? '')}${ids ? `\n<code>${esc(ids)}</code>` : ''}\n\nNo more alerts like this for this demo for 30 minutes.`;
}

return [{ json: { alert_at: at.toISOString(), demo, host, reason: b.reason, details, source: String(b.source ?? 'demo-proxy').slice(0, 60), text } }];

